"use client";

import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Lightbulb, ChevronDown, Star, CheckCircle, LayoutList, LayoutGrid, X, Phone, Globe, ExternalLink, MapPin } from "lucide-react";
import {
  mockSolutionProviders,
  solutionCategoryLabels,
  solutionCategoryIcons,
} from "@/lib/data";
import { cn } from "@/lib/utils";
import type { SolutionProvider } from "@/lib/types";

const countries = ["Todos los países", "Chile", "Argentina", "Colombia", "México", "España"];

const categoryOptions = [
  { value: "all", label: "Todos los tipos" },
  { value: "eficiencia_hidrica", label: "Huella hídrica" },
  { value: "eficiencia_energetica", label: "Eficiencia energética" },
  { value: "gestion_residuos", label: "Gestión de residuos" },
  { value: "educacion_ambiental", label: "Educación ambiental" },
  { value: "impacto_social", label: "Impacto social" },
  { value: "movilidad_sostenible", label: "Movilidad sostenible" },
];

const countryFlags: Record<string, string> = {
  "Todos los países": "🌎",
  Chile: "🇨🇱",
  Argentina: "🇦🇷",
  Colombia: "🇨🇴",
  México: "🇲🇽",
  España: "🇪🇸",
};

function StarRating({ stars, size = 14 }: { stars: number; size?: number }) {
  return (
    <div className="flex gap-0.5">
      {[1, 2, 3, 4, 5].map((s) => (
        <Star
          key={s}
          size={size}
          className={s <= stars ? "text-amber-400 fill-amber-400" : "text-slate-200 fill-slate-200"}
        />
      ))}
    </div>
  );
}

function BrandBadge({ name }: { name: string }) {
  const colors: Record<string, { bg: string; text: string }> = {
    Claro: { bg: "#E31E2D", text: "#fff" },
    ESPN: { bg: "#CC0000", text: "#fff" },
    VTR: { bg: "#E40046", text: "#fff" },
    Itaú: { bg: "#EC7000", text: "#fff" },
    Pemex: { bg: "#006B3F", text: "#fff" },
    Águila: { bg: "#FFD700", text: "#1a1a1a" },
  };
  const style = colors[name] ?? { bg: "#64748B", text: "#fff" };
  return (
    <div
      className="h-7 min-w-[52px] px-2.5 rounded-lg flex items-center justify-center text-xs font-bold"
      style={{ backgroundColor: style.bg, color: style.text }}
    >
      {name}
    </div>
  );
}

function ClubBadge({ name, initials }: { name: string; initials: string }) {
  return (
    <div
      title={name}
      className="w-8 h-8 rounded-full flex items-center justify-center text-[10px] font-bold text-white"
      style={{ background: "linear-gradient(135deg, #10B981, #06B6D4)" }}
    >
      {initials}
    </div>
  );
}

export default function SolutionsPage() {
  const [country, setCountry] = useState("Todos los países");
  const [category, setCategory] = useState("all");
  const [view, setView] = useState<"list" | "grid">("list");
  const [selected, setSelected] = useState<SolutionProvider | null>(null);

  const filtered = mockSolutionProviders.filter((p) => {
    const matchCountry = country === "Todos los países" || p.country === country;
    const matchCat = category === "all" || p.category === category;
    return matchCountry && matchCat;
  });

  return (
    <div className="max-w-7xl mx-auto space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div className="flex items-center gap-2.5">
          <Lightbulb size={22} className="text-amber-400" />
          <h1 className="text-xl font-bold text-slate-800 tracking-tight">Soluciones sostenibles</h1>
        </div>
        <div className="flex items-center gap-2 text-sm text-slate-400">
          <span>Patrocinado por</span>
          <div className="h-8 px-3 rounded-lg flex items-center justify-center text-xs font-bold text-white"
            style={{ backgroundColor: "#E31E2D" }}>
            Claro
          </div>
        </div>
      </div>

      {/* Filters + View toggle */}
      <div className="flex items-center gap-3 flex-wrap">
        {/* Country filter */}
        <div className="relative">
          <select
            value={country}
            onChange={(e) => setCountry(e.target.value)}
            className="input-field pl-8 pr-8 appearance-none cursor-pointer min-w-[180px]"
          >
            {countries.map((c) => (
              <option key={c} value={c} style={{ backgroundColor: "#fff" }}>
                {countryFlags[c]} {c}
              </option>
            ))}
          </select>
          <span className="absolute left-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-sm">
            {countryFlags[country]}
          </span>
          <ChevronDown size={13} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
        </div>

        {/* Category filter */}
        <div className="relative">
          <select
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="input-field pl-8 pr-8 appearance-none cursor-pointer min-w-[220px]"
          >
            {categoryOptions.map((o) => (
              <option key={o.value} value={o.value} style={{ backgroundColor: "#fff" }}>
                {o.value !== "all" ? solutionCategoryIcons[o.value] + " " : ""}{o.label}
              </option>
            ))}
          </select>
          <span className="absolute left-2.5 top-1/2 -translate-y-1/2 pointer-events-none text-sm">
            {category !== "all" ? solutionCategoryIcons[category] : "🔍"}
          </span>
          <ChevronDown size={13} className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
        </div>

        {/* View toggle */}
        <div className="ml-auto flex items-center gap-1 p-1 rounded-xl" style={{ backgroundColor: "#F1F5F9" }}>
          <button
            onClick={() => setView("list")}
            className={cn(
              "flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all",
              view === "list" ? "bg-white text-slate-800 shadow-sm" : "text-slate-400 hover:text-slate-600"
            )}
          >
            <LayoutList size={14} /> Lista
          </button>
          <button
            onClick={() => setView("grid")}
            className={cn(
              "flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all",
              view === "grid" ? "bg-white text-slate-800 shadow-sm" : "text-slate-400 hover:text-slate-600"
            )}
          >
            <LayoutGrid size={14} /> Grilla
          </button>
        </div>
      </div>

      {/* LIST VIEW */}
      {view === "list" && (
        <div className="card overflow-hidden">
          {/* Table header */}
          <div
            className="grid text-xs font-semibold uppercase tracking-wider px-6 py-3"
            style={{
              gridTemplateColumns: "48px 1fr 180px 100px 80px 120px",
              color: "#94A3B8",
              borderBottom: "1px solid #F1F5F9",
            }}
          >
            <span>Pos.</span>
            <span>Soluciones</span>
            <span>Total proyectos</span>
            <span>Marcas</span>
            <span>Clubes</span>
            <span>Clasificación</span>
          </div>

          {/* Rows */}
          <div className="divide-y divide-slate-50">
            <AnimatePresence>
              {filtered.map((p, i) => (
                <motion.div
                  key={p.id}
                  initial={{ opacity: 0, x: -8 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: i * 0.04 }}
                  className="grid items-center px-6 py-4 hover:bg-slate-50/60 cursor-pointer transition-colors"
                  style={{ gridTemplateColumns: "48px 1fr 180px 100px 80px 120px" }}
                  onClick={() => setSelected(p)}
                >
                  {/* Position */}
                  <span className="text-sm font-bold text-slate-400">{i + 1}</span>

                  {/* Solution info */}
                  <div className="flex items-center gap-3 min-w-0">
                    <div
                      className="w-9 h-9 rounded-xl flex items-center justify-center text-xs font-bold text-white flex-shrink-0"
                      style={{ backgroundColor: p.color }}
                    >
                      {p.initials}
                    </div>
                    <div className="min-w-0">
                      <div className="flex items-center gap-1.5">
                        <p className="font-semibold text-slate-800 text-sm truncate">{p.name}</p>
                        {p.verified && <CheckCircle size={12} className="text-teal-500 flex-shrink-0" />}
                      </div>
                      <p className="text-xs text-slate-400 truncate">
                        {p.flag} {p.country}, {solutionCategoryLabels[p.category]}
                      </p>
                    </div>
                  </div>

                  {/* Projects bar */}
                  <div className="flex items-center gap-3 pr-4">
                    <div className="flex-1 h-2 rounded-full overflow-hidden" style={{ backgroundColor: "#F1F5F9" }}>
                      <div
                        className="h-full rounded-full"
                        style={{
                          width: `${Math.min((p.projectsCount / 55) * 100, 100)}%`,
                          background: "linear-gradient(90deg, #10B981, #06B6D4)",
                        }}
                      />
                    </div>
                    <span className="text-sm font-bold text-slate-700 flex-shrink-0 w-6 text-right">{p.projectsCount}</span>
                  </div>

                  {/* Brand */}
                  <div>
                    {p.associatedBrand && <BrandBadge name={p.associatedBrand} />}
                  </div>

                  {/* Club */}
                  <div>
                    {p.associatedClub && (
                      <ClubBadge
                        name={p.associatedClub}
                        initials={p.associatedClub.split(" ").map((w) => w[0]).slice(0, 2).join("")}
                      />
                    )}
                  </div>

                  {/* Stars */}
                  <StarRating stars={p.stars} />
                </motion.div>
              ))}
            </AnimatePresence>
          </div>

          {filtered.length === 0 && (
            <div className="text-center py-16">
              <Lightbulb size={36} className="mx-auto text-slate-200 mb-3" />
              <p className="text-slate-400 font-medium">No se encontraron soluciones</p>
              <p className="text-slate-300 text-sm mt-1">Prueba con otros filtros</p>
            </div>
          )}
        </div>
      )}

      {/* GRID VIEW */}
      {view === "grid" && (
        <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-5">
          <AnimatePresence>
            {filtered.map((p, i) => (
              <motion.div
                key={p.id}
                initial={{ opacity: 0, y: 16 }}
                animate={{ opacity: 1, y: 0 }}
                transition={{ delay: i * 0.05 }}
                className="card-hover p-5 flex flex-col gap-4 cursor-pointer"
                style={{ borderTop: `3px solid ${p.color}` }}
                onClick={() => setSelected(p)}
              >
                <div className="flex items-center gap-3">
                  <div
                    className="w-11 h-11 rounded-xl flex items-center justify-center text-sm font-bold text-white flex-shrink-0"
                    style={{ backgroundColor: p.color }}
                  >
                    {p.initials}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-1.5">
                      <p className="font-bold text-slate-800 truncate">{p.name}</p>
                      {p.verified && <CheckCircle size={12} className="text-teal-500 flex-shrink-0" />}
                    </div>
                    <p className="text-xs text-slate-400">{p.flag} {p.country}</p>
                  </div>
                  <span
                    className="text-xs font-semibold px-2 py-0.5 rounded-full flex-shrink-0"
                    style={{ backgroundColor: `${p.color}18`, color: p.color }}
                  >
                    {solutionCategoryIcons[p.category]}
                  </span>
                </div>

                <p className="text-sm text-slate-500 line-clamp-2 leading-relaxed">{p.description}</p>

                <div className="flex items-center justify-between pt-1 border-t border-slate-50">
                  <div className="flex items-center gap-3">
                    {p.associatedBrand && <BrandBadge name={p.associatedBrand} />}
                    {p.associatedClub && (
                      <ClubBadge
                        name={p.associatedClub}
                        initials={p.associatedClub.split(" ").map((w) => w[0]).slice(0, 2).join("")}
                      />
                    )}
                  </div>
                  <StarRating stars={p.stars} size={13} />
                </div>

                <div className="flex items-center gap-2 text-xs text-slate-400">
                  <div className="flex-1 h-1.5 rounded-full overflow-hidden" style={{ backgroundColor: "#F1F5F9" }}>
                    <div
                      className="h-full rounded-full"
                      style={{
                        width: `${Math.min((p.projectsCount / 55) * 100, 100)}%`,
                        background: "linear-gradient(90deg, #10B981, #06B6D4)",
                      }}
                    />
                  </div>
                  <span className="font-semibold text-slate-600">{p.projectsCount} proyectos</span>
                </div>
              </motion.div>
            ))}
          </AnimatePresence>

          {filtered.length === 0 && (
            <div className="col-span-3 text-center py-16">
              <Lightbulb size={36} className="mx-auto text-slate-200 mb-3" />
              <p className="text-slate-400 font-medium">No se encontraron soluciones</p>
            </div>
          )}
        </div>
      )}

      {/* Detail modal */}
      <AnimatePresence>
        {selected && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex items-center justify-center p-4"
            style={{ backgroundColor: "rgba(0,0,0,0.65)", backdropFilter: "blur(6px)" }}
            onClick={() => setSelected(null)}
          >
            <motion.div
              initial={{ scale: 0.95, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.95, y: 20 }}
              className="card max-w-lg w-full overflow-hidden max-h-[85vh] overflow-y-auto"
              onClick={(e) => e.stopPropagation()}
            >
              <div className="h-1.5 w-full" style={{ backgroundColor: selected.color }} />
              <div className="p-6">
                <div className="flex items-start gap-4 mb-5">
                  <div
                    className="w-14 h-14 rounded-2xl flex items-center justify-center text-lg font-bold text-white flex-shrink-0"
                    style={{ backgroundColor: selected.color }}
                  >
                    {selected.initials}
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <h2 className="text-lg font-bold text-slate-900">{selected.name}</h2>
                      {selected.verified && (
                        <span className="flex items-center gap-1 text-xs font-semibold px-2 py-0.5 rounded-full"
                          style={{ backgroundColor: "rgba(16,185,129,0.1)", color: "#10B981" }}>
                          <CheckCircle size={10} /> Verificada
                        </span>
                      )}
                    </div>
                    <p className="text-sm text-slate-400 mt-0.5 flex items-center gap-1">
                      <MapPin size={12} /> {selected.flag} {selected.country}
                    </p>
                    <div className="mt-1.5">
                      <span
                        className="text-xs font-semibold px-2 py-0.5 rounded-full"
                        style={{ backgroundColor: `${selected.color}18`, color: selected.color }}
                      >
                        {solutionCategoryIcons[selected.category]} {solutionCategoryLabels[selected.category]}
                      </span>
                    </div>
                  </div>
                  <button
                    onClick={() => setSelected(null)}
                    className="flex-shrink-0 w-8 h-8 rounded-full flex items-center justify-center hover:bg-slate-100"
                  >
                    <X size={16} className="text-slate-400" />
                  </button>
                </div>

                <p className="text-sm text-slate-600 leading-relaxed mb-5">{selected.description}</p>

                {/* Stats row */}
                <div className="grid grid-cols-3 gap-3 mb-5">
                  <div className="text-center p-3 rounded-xl" style={{ backgroundColor: "#F8FAFC" }}>
                    <p className="text-xl font-bold text-slate-900">{selected.projectsCount}</p>
                    <p className="text-xs text-slate-400 mt-0.5">Proyectos</p>
                  </div>
                  <div className="text-center p-3 rounded-xl" style={{ backgroundColor: "#F8FAFC" }}>
                    <StarRating stars={selected.stars} />
                    <p className="text-xs text-slate-400 mt-1">Clasificación</p>
                  </div>
                  <div className="text-center p-3 rounded-xl" style={{ backgroundColor: "#F8FAFC" }}>
                    <div className="flex justify-center">
                      {selected.associatedBrand && <BrandBadge name={selected.associatedBrand} />}
                    </div>
                    <p className="text-xs text-slate-400 mt-1">Marca</p>
                  </div>
                </div>

                {/* Services */}
                <div className="mb-5">
                  <p className="text-xs font-semibold text-slate-400 uppercase tracking-wider mb-3">Servicios</p>
                  <div className="grid grid-cols-2 gap-2">
                    {selected.services.map((s) => (
                      <div key={s} className="flex items-center gap-2 text-sm text-slate-700">
                        <div className="w-1.5 h-1.5 rounded-full flex-shrink-0" style={{ backgroundColor: selected.color }} />
                        {s}
                      </div>
                    ))}
                  </div>
                </div>

                {selected.tags && selected.tags.length > 0 && (
                  <div className="flex flex-wrap gap-2 mb-6">
                    {selected.tags.map((t) => (
                      <span key={t} className="text-xs px-2.5 py-1 rounded-full font-medium"
                        style={{ backgroundColor: "#F1F5F9", color: "#64748B" }}>
                        {t}
                      </span>
                    ))}
                  </div>
                )}

                <div className="flex gap-3">
                  <button className="btn-primary flex-1 justify-center gap-2">
                    <Phone size={14} /> Contactar
                  </button>
                  <button className="btn-secondary gap-2">
                    <Globe size={14} /> Web <ExternalLink size={12} />
                  </button>
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}
